import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";
import { toNew, toOld } from "./timemap";

// JP CONSTRUÇÃO (Rafael) · "Quer construir ou reformar sem dor de cabeça?". Motion vertical de 32,4 s sobre a locução
// (ElevenLabs, voz o locutor, 30,9 s, entra em 0,15 s). Identidade do logo: azul-marinho, laranja da janela, azul-claro da gota,
// Poppins pesada. Base de estilo: referência "aplicativo de treino" (frase montando palavra a palavra + palavra-chave em pílula),
// trocando o vermelho pelas cores da JP. Pedido do cliente: sem emojis e gente logo no começo (abre com a equipe cortando porcelanato).
// Tempos = tempo da palavra na voz (edit/transcripts/voz-v1.json); `t` já desconta a entrada da locução.

const { fontFamily: F } = loadPoppins("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const RJ_FPS = 30;
const LEAD = 0.15;
// v4: voz v2 termina em "papel" (sem "clique no link"); a marca fica ~1,7 s e fecha
export const RJ_FRAMES = Math.round(32.05 * RJ_FPS);

const NAVY = "#01225B";
const DEEP = "#00163D";
const PANEL = "#0A3176";
const EDGE = "rgba(255,255,255,0.14)";
const ORANGE = "#F97C25";
const BLUE = "#01B1FD";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
// tempos das cenas estão na voz v1; `fr` leva para o quadro do vídeo pela voz v2
const fr = (s: number) => Math.round((toNew(s) + LEAD) * RJ_FPS);
const sp = (t: number, a: number, damping = 14, stiffness = 170) =>
  spring({ frame: Math.round((t - a) * RJ_FPS), fps: RJ_FPS, config: { damping, stiffness } });

// ───────── texto: frase pequena montando palavra a palavra + palavra-chave em pílula ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number }> = ({ t, words, size = 54 }) => (
  <div style={{ fontFamily: F, fontWeight: 600, fontSize: size, lineHeight: 1.2, color: WHITE, textAlign: "center", whiteSpace: "nowrap", textShadow: "0 4px 24px rgba(0,10,35,0.55)" }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.28);
      return <span key={i} style={{ display: "inline-block", margin: "0 0.13em", opacity: q, transform: `translateY(${(1 - q) * 20}px)`, filter: `blur(${(1 - q) * 9}px)` }}>{w}</span>;
    })}
  </div>
);
const Pill: React.FC<{ t: number; at: number; text: string; color?: string; size?: number; ink?: string }> = ({ t, at, text, color = ORANGE, size = 104, ink = WHITE }) => {
  const s = sp(t, at, 13, 230);
  return (
    <div style={{ display: "inline-block", padding: `${size * 0.04}px ${size * 0.34}px ${size * 0.1}px`, borderRadius: size * 0.22, background: color, color: ink, fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.02em", whiteSpace: "nowrap", opacity: Math.min(1, s * 3), transform: `scale(${0.55 + 0.45 * s})`, boxShadow: `0 18px 50px ${color}55` }}>{text}</div>
  );
};
const Block: React.FC<{ t: number; top: number; at: number; out?: number; children: React.ReactNode }> = ({ t, top, at, out, children }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.12)) return null;
  const o = out === undefined ? 0 : k(t, out, 0.1);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 22, opacity: 1 - o, transform: `translateY(${-o * 24}px)` }}>{children}</div>
  );
};

// ───────── vídeo do cliente ─────────
type Cut = { src: "obra" | "pool"; a: number; b: number; start: number; z0: number; z1: number; ox: number; oy: number; dx?: number; rate?: number };
const Footage: React.FC<{ t: number; cuts: Cut[] }> = ({ t, cuts }) => (
  <AbsoluteFill style={{ overflow: "hidden", background: DEEP }}>
    {cuts.map((c, i) => {
      const p = lin(t, c.a, c.b);
      const z = c.z0 + (c.z1 - c.z0) * p;
      return (
        <Sequence key={i} from={fr(c.a)} durationInFrames={Math.max(1, fr(c.b) - fr(c.a))} layout="none">
          <AbsoluteFill style={{ transform: `translateX(${(c.dx ?? 0) * p}px) scale(${z.toFixed(4)})`, transformOrigin: `${c.ox}% ${c.oy}%` }}>
            <OffthreadVideo muted src={staticFile(`rafaeljp/${c.src}.mp4`)} trimBefore={Math.round(c.start * RJ_FPS)} playbackRate={c.rate ?? 1} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </AbsoluteFill>
        </Sequence>
      );
    })}
  </AbsoluteFill>
);
const Scrim: React.FC<{ low?: boolean }> = ({ low = true }) => (
  <AbsoluteFill style={{ background: low
    ? "linear-gradient(180deg, rgba(0,22,61,0) 40%, rgba(0,22,61,0.72) 66%, rgba(0,22,61,0.92) 100%)"
    : "linear-gradient(180deg, rgba(0,22,61,0.9) 0%, rgba(0,22,61,0.6) 26%, rgba(0,22,61,0) 48%)" }} />
);
const flash = (t: number, ats: number[], d = 0.2) => ats.reduce((m, a) => Math.max(m, t >= a && t < a + d ? 1 - (t - a) / d : 0), 0);
const Flash: React.FC<{ t: number; ats: number[]; o?: number }> = ({ t, ats, o = 0.35 }) => <AbsoluteFill style={{ background: WHITE, opacity: o * flash(t, ats), pointerEvents: "none" }} />;

// fundo liso da marca, com um respiro de luz no centro
const Bg: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 80% 55% at 50% 52%, #06307A 0%, ${NAVY} 55%, ${DEEP} 100%)` }} />;

// ───────── ícones desenhados (traço branco, detalhe laranja) ─────────
const S = { fill: "none", stroke: WHITE, strokeWidth: 7, strokeLinecap: "round", strokeLinejoin: "round" } as const;
const IcoBrick: React.FC<{ c?: string }> = ({ c = ORANGE }) => (
  <svg viewBox="0 0 120 120" width="100%" height="100%">
    {[0, 1, 2, 3].map((r) => [0, 1, 2].map((j) => <rect key={`${r}${j}`} x={(r % 2 ? -18 : 4) + j * 40} y={14 + r * 24} width={34} height={18} rx={3} fill={r === 1 && j === 1 ? c : "none"} stroke={WHITE} strokeWidth={5} />))}
  </svg>
);
const IcoHouse: React.FC<{ c?: string }> = ({ c = ORANGE }) => (
  <svg viewBox="0 0 120 120" width="100%" height="100%">
    <path d="M14 58 L60 18 L106 58" {...S} />
    <path d="M26 50 V102 H94 V50" {...S} />
    <rect x={48} y={68} width={24} height={34} fill={c} rx={3} />
  </svg>
);
const IcoRoller: React.FC<{ c?: string }> = ({ c = ORANGE }) => (
  <svg viewBox="0 0 120 120" width="100%" height="100%">
    <rect x={14} y={16} width={74} height={30} rx={8} fill={c} />
    <path d="M88 31 H102 V62 H58 V78" {...S} />
    <rect x={50} y={78} width={16} height={30} rx={5} fill={WHITE} />
  </svg>
);
const IcoWrench: React.FC<{ c?: string; bg?: string }> = ({ c = ORANGE, bg = PANEL }) => (
  <svg viewBox="0 0 120 120" width="100%" height="100%">
    <g transform="rotate(-45 60 60)">
      <rect x={52} y={44} width={16} height={68} rx={8} fill={WHITE} />
      <circle cx={60} cy={34} r={24} fill={c} />
      <rect x={52} y={6} width={16} height={28} fill={bg} />
    </g>
  </svg>
);
const IcoHelmet: React.FC = () => (
  <svg viewBox="0 0 160 120" width="100%" height="100%">
    <path d="M24 86 C24 44, 52 22, 80 22 C108 22, 136 44, 136 86 Z" fill={WHITE} />
    <rect x={70} y={14} width={20} height={56} rx={9} fill={ORANGE} />
    <rect x={10} y={84} width={140} height={18} rx={9} fill={WHITE} />
  </svg>
);
const IcoBarcode: React.FC = () => (
  <svg viewBox="0 0 120 80" width="100%" height="100%">
    {[6, 16, 22, 34, 40, 52, 62, 68, 80, 88, 98, 106].map((x, i) => <rect key={i} x={x} y={10} width={i % 3 ? 4 : 7} height={60} fill={WHITE} />)}
  </svg>
);
const IcoDiamond: React.FC = () => (
  <svg viewBox="0 0 120 120" width="100%" height="100%">
    <rect x={28} y={28} width={64} height={64} rx={12} transform="rotate(45 60 60)" fill="none" stroke={BLUE} strokeWidth={10} />
    <circle cx={60} cy={60} r={9} fill={BLUE} />
  </svg>
);
const IcoCard: React.FC = () => (
  <svg viewBox="0 0 120 84" width="100%" height="100%">
    <rect x={6} y={6} width={108} height={72} rx={10} fill="none" stroke={WHITE} strokeWidth={6} />
    <rect x={6} y={22} width={108} height={12} fill={WHITE} />
    <rect x={18} y={50} width={22} height={14} rx={3} fill={ORANGE} />
  </svg>
);

// ───────── cena 1 · gente logo de cara: equipe cortando porcelanato, o dono na piscina pronta ─────────
// v4: abertura calma. A gente aparece só no primeiro plano, para chamar atenção (equipe cortando porcelanato, um plano só,
// aproximando devagar); "sem dor de cabeça" já vai para uma piscina pronta. Antes eram 5 cortes em 3,5 s e o o diretor achou atropelado.
const OPEN: Cut[] = [
  { src: "obra", a: -0.15, b: 2.0, start: 24.9, z0: 1.03, z1: 1.16, ox: 55, oy: 8 },
  { src: "pool", a: 2.0, b: 3.45, start: 25.5, z0: 1.14, z1: 1.04, ox: 50, oy: 55 },
];
const S1: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill>
    <Footage t={t} cuts={OPEN} />
    <Scrim />
    <Flash t={t} ats={[2.0]} o={0.3} />
    <Block t={t} top={1290} at={0} out={1.95}>
      <Words t={t} words={[["Quer", 0.05], ["construir", 0.25]]} size={60} />
      <Pill t={t} at={1.02} text="ou reformar" />
    </Block>
    <Block t={t} top={1290} at={2.04} out={3.33}>
      <Words t={t} words={[["sem", 2.05]]} size={60} />
      <Pill t={t} at={2.27} text="dor de cabeça?" size={90} />
    </Block>
  </AbsoluteFill>
);

// ───────── cena 2 · a marca ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const s = sp(t, 3.55, 13, 140);
  const n = k(t, 4.05, 0.45);
  const cam = 1 + 0.07 * lin(t, 3.45, 4.75);
  return (
    <AbsoluteFill>
      <Bg />
      <AbsoluteFill style={{ transform: `scale(${cam})` }}>
        <div style={{ position: "absolute", left: 540 - 300, top: 560, width: 600, height: 504, transform: `translateY(${(1 - s) * 260}px) scale(${0.55 + 0.45 * s})`, opacity: Math.min(1, s * 3) }}>
          <Img src={staticFile("rafaeljp/simbolo.png")} style={{ width: "100%", height: "100%", filter: "drop-shadow(0 30px 60px rgba(0,0,0,0.45))" }} />
        </div>
        <div style={{ position: "absolute", left: 540 - 380, top: 1120, width: 760, height: 190, opacity: n, transform: `translateY(${(1 - n) * 40}px)`, filter: `blur(${(1 - n) * 10}px)` }}>
          <Img src={staticFile("rafaeljp/nome.png")} style={{ width: "100%", height: "100%" }} />
        </div>
      </AbsoluteFill>
      <Flash t={t} ats={[3.45]} o={0.5} />
    </AbsoluteFill>
  );
};

// ───────── cena 3 · especialista em piscinas (piscinas prontas, tela cheia) ─────────
const POOL: Cut[] = [
  { src: "pool", a: 4.72, b: 6.5, start: 14.0, z0: 1.05, z1: 1.18, ox: 50, oy: 60 },
  { src: "obra", a: 6.5, b: 7.42, start: 13.2, z0: 1.22, z1: 1.1, ox: 50, oy: 50, dx: 30 },
];
// entra subindo por cima da marca, rápido e desfocado
const S3: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ transform: `translateY(${(1 - k(t, 4.72, 0.24)) * 1100}px)`, filter: `blur(${(1 - k(t, 4.72, 0.24)) * 16}px)` }}>
    <Footage t={t} cuts={POOL} />
    <Scrim low={false} />
    <Flash t={t} ats={[6.5]} o={0.25} />
    <Block t={t} top={250} at={4.8} out={6.42}>
      <Words t={t} words={[["especialista", 4.81], ["em", 5.69]]} size={60} />
      <Pill t={t} at={5.79} text="piscinas" color={BLUE} size={120} ink={DEEP} />
    </Block>
    <Block t={t} top={300} at={6.52}>
      <Words t={t} words={[["e", 6.53], ["também", 6.63], ["trabalha", 6.89], ["com", 7.29]]} size={60} />
    </Block>
  </AbsoluteFill>
);

// ───────── cena 4 · construções, reformas, pinturas, pequenos reparos (um bloco por palavra) ─────────
const SERV: { label: string; at: number; Ico: React.FC }[] = [
  { label: "Construções", at: 7.47, Ico: IcoBrick },
  { label: "Reformas", at: 8.33, Ico: IcoHouse },
  { label: "Pinturas", at: 9.11, Ico: IcoRoller },
  { label: "Pequenos reparos", at: 9.87, Ico: IcoWrench },
];
const S4: React.FC<{ t: number }> = ({ t }) => {
  let act = 0;
  SERV.forEach((s, i) => { if (t >= s.at) act = i; });
  const pos = SERV.map((_, i) => [(i % 2) * 420 - 210, Math.floor(i / 2) * 440 - 220]);
  // a câmera vai até o bloco que está sendo falado e, no último, abre para ver os quatro
  const ease = k(t, SERV[act].at - 0.05, 0.4);
  const prev = act ? pos[act - 1] : [0, 0];
  const cx = prev[0] + (pos[act][0] - prev[0]) * ease;
  const cy = prev[1] + (pos[act][1] - prev[1]) * ease;
  const zoomOut = k(t, 10.4, 0.6);
  const z = 1.07 - 0.1 * zoomOut;
  const enter = k(t, 7.4, 0.3);
  return (
    <AbsoluteFill>
      <Bg />
      <AbsoluteFill style={{ transform: `scale(${z * (0.9 + 0.1 * enter)}) translate(${-cx * 0.22 * (1 - zoomOut)}px, ${-cy * 0.22 * (1 - zoomOut)}px)` }}>
        {SERV.map(({ label, at, Ico }, i) => {
          const s = sp(t, at - 0.04, 13, 200);
          const on = i === act && t < 10.9;
          return (
            <div key={i} style={{ position: "absolute", left: 540 + pos[i][0] - 190, top: 1000 + pos[i][1] - 200, width: 380, height: 400, boxSizing: "border-box", borderRadius: 40, background: on ? ORANGE : PANEL, border: `2px solid ${on ? ORANGE : EDGE}`, boxShadow: on ? `0 30px 80px ${ORANGE}55` : "0 24px 60px rgba(0,0,0,0.35)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 26, opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * 120}px) scale(${0.7 + 0.3 * s})` }}>
              <div style={{ width: 170, height: 170 }}>{on ? <OnIco Ico={Ico} /> : <Ico />}</div>
              <div style={{ fontFamily: F, fontWeight: 700, fontSize: label.length > 12 ? 36 : 42, color: WHITE, textAlign: "center", lineHeight: 1.1 }}>{label}</div>
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
// no bloco ativo (fundo laranja) o detalhe do ícone vira marinho para não sumir
const OnIco: React.FC<{ Ico: React.FC<{ c?: string; bg?: string }> }> = ({ Ico }) => <Ico c={NAVY} bg={ORANGE} />;

// ───────── cena 5 · nossa equipe + telhados, pisos, revestimentos, alvenaria ─────────
const TEAM: Cut[] = [
  { src: "obra", a: 11.2, b: 12.56, start: 37.9, z0: 1.35, z1: 1.5, ox: 33, oy: 56, rate: 0.5 },
  { src: "obra", a: 13.96, b: 15.26, start: 28.4, z0: 1.05, z1: 1.2, ox: 50, oy: 70 },
];
const Roof: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const w = k(t, at, 0.5);
  return (
    <svg width={760} height={700} viewBox="0 0 760 700" style={{ overflow: "visible" }}>
      <defs><clipPath id="rjroof"><path d="M30 330 L380 40 L730 330 Z" /></clipPath></defs>
      <path d="M110 330 V660 H650 V330" fill="none" stroke={WHITE} strokeWidth={12} strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - w} />
      <rect x={320} y={500} width={120} height={160} rx={8} fill={WHITE} opacity={w} />
      <g clipPath="url(#rjroof)">
        {[0, 1, 2, 3, 4, 5].map((r) => {
          const s = sp(t, at + 0.12 + (5 - r) * 0.1, 15, 220);
          return (
            <g key={r} transform={`translate(0 ${(1 - s) * -260})`} opacity={Math.min(1, s * 3)}>
              {Array.from({ length: 16 }, (_, j) => (
                <rect key={j} x={(r % 2 ? -24 : 0) + j * 50} y={40 + r * 50} width={46} height={46} rx={10} fill={r % 2 ? ORANGE : "#E86B15"} />
              ))}
            </g>
          );
        })}
      </g>
      <path d="M10 346 L380 30 L750 346" fill="none" stroke={WHITE} strokeWidth={16} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - k(t, at + 0.65, 0.35)} />
    </svg>
  );
};
const Wall: React.FC<{ t: number; at: number }> = ({ t, at }) => (
  <svg width={780} height={520} viewBox="0 0 780 520" style={{ overflow: "visible" }}>
    {Array.from({ length: 6 }, (_, r) =>
      Array.from({ length: r % 2 ? 6 : 5 }, (_, j) => {
        const i = r * 6 + j;
        const s = sp(t, at + 0.04 * i + (5 - r) * 0.02, 15, 240);
        const x = r % 2 ? -80 + j * 160 : j * 160;
        return <rect key={i} x={Math.max(0, x)} y={(5 - r) * 86} width={x < 0 ? 150 + x : Math.min(150, 780 - x)} height={76} rx={8} fill={(r + j) % 3 ? "#E86B15" : ORANGE} transform={`translate(0 ${(1 - s) * -220})`} opacity={Math.min(1, s * 3)} />;
      }),
    )}
  </svg>
);
const S5: React.FC<{ t: number }> = ({ t }) => {
  const inRoof = t >= 12.56 && t < 13.96;
  const inTile = t >= 15.26 && t < 16.26;
  const inWall = t >= 16.26;
  const card = sp(t, 15.26, 15, 180);
  return (
    <AbsoluteFill>
      {(t < 12.56 || (t >= 13.96 && t < 15.26)) && <><Footage t={t} cuts={TEAM} /><Scrim /></>}
      {inRoof && (
        <AbsoluteFill>
          <Bg />
          <AbsoluteFill style={{ transform: `scale(${1.1 - 0.08 * lin(t, 12.56, 13.96)}) rotate(${-1.5 + 1.5 * k(t, 12.56, 0.6)}deg)` }}>
            <div style={{ position: "absolute", left: 160, top: 560 }}><Roof t={t} at={12.6} /></div>
          </AbsoluteFill>
        </AbsoluteFill>
      )}
      {inTile && (
        <AbsoluteFill>
          <Bg />
          <div style={{ position: "absolute", left: 160, top: 470, width: 760, height: 900, borderRadius: 44, overflow: "hidden", border: `3px solid ${EDGE}`, boxShadow: "0 40px 100px rgba(0,0,0,0.5)", transform: `translateY(${(1 - card) * 500}px) rotate(${(1 - card) * 6}deg)` }}>
            <Footage t={t} cuts={[{ src: "obra", a: 15.26, b: 16.26, start: 33.3, z0: 1.0, z1: 1.14, ox: 50, oy: 45 }]} />
          </div>
        </AbsoluteFill>
      )}
      {inWall && (
        <AbsoluteFill>
          <Bg />
          <AbsoluteFill style={{ transform: `scale(${1.06 - 0.06 * lin(t, 16.26, 17.9)}) translateY(${-30 * lin(t, 16.26, 17.9)}px)` }}>
            <div style={{ position: "absolute", left: 150, top: 760 }}><Wall t={t} at={16.3} /></div>
          </AbsoluteFill>
        </AbsoluteFill>
      )}
      <Flash t={t} ats={[12.56, 13.96, 16.26]} o={0.28} />
      <Block t={t} top={1300} at={11.24} out={12.48}>
        <Words t={t} words={[["Nossa", 11.25]]} size={60} />
        <Pill t={t} at={11.47} text="equipe" />
      </Block>
      <Block t={t} top={250} at={12.58} out={13.9}>
        <Words t={t} words={[["manutenção", 12.59], ["de", 13.13]]} size={58} />
        <Pill t={t} at={13.25} text="telhados" />
      </Block>
      <Block t={t} top={1300} at={13.98} out={15.2}>
        <Words t={t} words={[["instalação", 13.99], ["de", 14.55]]} size={58} />
        <Pill t={t} at={14.73} text="pisos" />
      </Block>
      <Block t={t} top={1420} at={15.28} out={16.2}>
        <Pill t={t} at={15.29} text="revestimentos" size={88} />
      </Block>
      <Block t={t} top={250} at={16.28} out={17.82}>
        <Words t={t} words={[["serviços", 16.29], ["de", 16.79]]} size={58} />
        <Pill t={t} at={16.89} text="alvenaria" />
      </Block>
    </AbsoluteFill>
  );
};

// ───────── cena 6 · contrato + suporte técnico do engenheiro ─────────
const S6: React.FC<{ t: number }> = ({ t }) => {
  const e = k(t, 17.86, 0.28);
  const doc = sp(t, 17.9, 15, 170);
  const sig = k(t, 18.4, 0.45);
  const stamp = sp(t, 18.85, 11, 260);
  const away = k(t, 18.97, 0.3);
  const helm = sp(t, 19.05, 13, 180);
  const ring = k(t, 19.15, 0.9);
  return (
    <AbsoluteFill style={{ transform: `translateX(${(1 - e) * 420}px)`, filter: `blur(${(1 - e) * 12}px)` }}>
      <Bg />
